-- TikTok X migration 002: business profiles, digital IDs and music usage
CREATE TABLE IF NOT EXISTS business_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,business_name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT '',website VARCHAR(255) NOT NULL DEFAULT '',contact_email VARCHAR(190) NOT NULL DEFAULT '',description VARCHAR(1000) NOT NULL DEFAULT '',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS digital_ids(user_id BIGINT UNSIGNED PRIMARY KEY,public_id CHAR(36) NOT NULL UNIQUE,display_public TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS music_uses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,music_id BIGINT UNSIGNED NOT NULL,video_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_music_video(music_id,video_id),FOREIGN KEY(music_id) REFERENCES music(id) ON DELETE CASCADE,FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
